import { BooleanColumn, GenericColumn, ReferenceColumn, StringColumn, Table } from '../../../db'

export const sys_atf_test = Table({
    name: 'sys_atf_test',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        copied_from: ReferenceColumn({
            mandatory: false,
            label: 'Copied from',
            read_only: true,
            active: true,
            referenceTable: 'sys_atf_test',
        }),
        description: StringColumn({
            mandatory: false,
            label: 'Description',
            read_only: false,
            active: true,
            maxLength: 1000,
            dropdown: 'none',
        }),
        enable_parameterized_testing: BooleanColumn({
            mandatory: false,
            label: 'Enable parameterized testing',
            read_only: false,
            active: true,
        }),
        fail_on_server_error: BooleanColumn({
            mandatory: false,
            label: 'Fail on server error',
            read_only: false,
            active: true,
            default: false,
        }),
        name: StringColumn({
            mandatory: true,
            label: 'Name',
            read_only: false,
            active: true,
            default: 'My New Test',
            maxLength: 100,
            dropdown: 'none',
        }),
        parameters: GenericColumn({
            mandatory: false,
            label: 'Parameters',
            read_only: false,
            active: true,
            column_type: 'glide_var',
        }),
        remember: GenericColumn({
            mandatory: false,
            label: 'Remembered values',
            read_only: false,
            active: true,
            column_type: 'glide_var',
        }),
        sn_atf_tg_generated: BooleanColumn({
            mandatory: false,
            label: 'Generated',
            read_only: true,
            active: true,
            default: false,
        }),
    },
})
